// Compose markdown summary from the Postgres aggregate row + webhook dates.
const row = $input.first().json;
const webhookData = $('Webhook').first().json.body || {};
const startDate = webhookData.start_date || 'unknown';
const endDate = webhookData.end_date || 'unknown';

const detections = row.detections != null ? Number(row.detections) : 0;
const uniqueVessels = row.unique_vessels != null ? Number(row.unique_vessels) : 0;
const avgWaveRaw = row.avg_wave_h_m;
const avgWave = avgWaveRaw != null ? Number(avgWaveRaw).toFixed(2) : 'n/a';

const summary = [
  `## Sundahöfn activity ${startDate} → ${endDate}`,
  '',
  `- Camera detections: ${detections.toLocaleString('en-US')}`,
  `- Unique vessels at port (GFW): ${uniqueVessels}`,
  `- Avg wave height: ${avgWave} m`,
].join('\n');

return [{ json: { summary } }];
